import { Navigate, Route, Routes, useNavigate } from 'react-router-dom'
import { MapPin, WashingMachine } from 'lucide-react'
import { currentSession, signInAs, signOut } from '@laundry-desk/shared-ui'

function CustomerLogin(){const navigate=useNavigate();return <main className="shell"><section className="card"><div className="mark"><WashingMachine/></div><p className="eyebrow">LAUNDRY DESK</p><h1>Cuci jadi lebih dekat.</h1><p>Temukan outlet sekitar, pilih layanan, lalu pantau pesananmu.</p><button onClick={()=>{signInAs('customer');navigate('/pelanggan')}}>Masuk sebagai pelanggan demo</button><small>Akun pelanggan akan tersambung ke Laravel Sanctum pada tahap backend.</small></section></main>}
function CustomerHome(){const user=currentSession();const navigate=useNavigate();if(!user||user.role!=='customer')return <Navigate to="/masuk" replace/>;return <main className="customer"><header><div className="logo"><WashingMachine size={22}/> Laundry Desk</div><button className="link" onClick={()=>{signOut();navigate('/masuk')}}>Keluar</button></header><section className="hero"><p className="eyebrow">HALO, {user.name.toUpperCase()}</p><h1>Pilih outlet terdekat</h1><p>Izinkan lokasi agar outlet bisa diurutkan berdasarkan jarak.</p><article><MapPin color="#397fa6"/><div><b>Gunakan lokasi saya</b><span>Hanya dipakai untuk mencari outlet sekitar.</span></div></article><div className="map-placeholder">Peta outlet akan memakai penyedia peta yang dipilih pada tahap fitur pelanggan.</div><button>Lanjut pilih layanan</button></section></main>}
export function App(){return <Routes><Route path="/masuk" element={<CustomerLogin/>}/><Route path="/pelanggan" element={<CustomerHome/>}/><Route path="*" element={<Navigate to={currentSession()?.role==='customer'?'/pelanggan':'/masuk'} replace/>}/></Routes>}
